/**
 * The campaigns this endpoint serves. A campaign supplies its own form definition, its own
 * routing and its own copy; everything else (storage, the register lookup, delivery,
 * alerts, tracking) is shared. Adding a campaign is one entry here plus its folder under g/.
 *
 * The page data (config, copy, the landing page split around the form) is generated by
 * scripts/build-g-growth.mjs into data.generated.mjs.
 */
import * as growthCore from '../../../g/uk-it-growth/core.mjs';
import * as growthRoute from '../../../g/uk-it-growth/route.mjs';
import { renderForm as growthRenderForm } from '../../../g/uk-it-growth/render-form.mjs';
import { growth } from './data.generated.mjs';

export const campaigns = {
  [growth.cfg.campaign]: {
    id: growth.cfg.campaign,
    cfg: growth.cfg,
    copy: growth.copy,
    shell: growth.shell,
    core: growthCore,
    route: growthRoute,
    renderForm: growthRenderForm,
    /** The name looked up in Companies House. */
    registryName: (values) => values.company_name,
    /** Routes that count as a qualified form for Meta (Conversions API and pixel). */
    qualifiedRoutes: ['fit', 'review'],
  },
};
